class CurrencyConverter:
    USD = 1.0
    EUR = 0.85
    GBP = 0.72
    JPY = 110.15
    CAD = 1.23
    AUD = 1.34
    CNY = 6.40  # Could be further replaced, but we'll keep it simple with constants

    def __init__(self):
        self.rates = {
            'USD': self.USD,
            'EUR': self.EUR,
            'GBP': self.GBP,
            'JPY': self.JPY,
            'CAD': self.CAD,
            'AUD': self.AUD,
            'CNY': self.CNY,
        }

    def convert(self, amount, from_currency, to_currency):
        if from_currency == to_currency:
            return amount

        if not self._is_currency_supported(from_currency) or not self._is_currency_supported(to_currency):
            return False

        converted_amount = self._calculate_converted_amount(amount, from_currency, to_currency)
        return converted_amount

    def _is_currency_supported(self, currency):
        return currency in self.rates

    def _calculate_converted_amount(self, amount, from_currency, to_currency):
        from_rate = self.rates[from_currency]
        to_rate = self.rates[to_currency]
        return (amount / from_rate) * to_rate

    def get_supported_currencies(self):
        return self._get_supported_currencies()

    def _get_supported_currencies(self):
        return list(self.rates.keys())

    def add_currency_rate(self, currency, rate):
        if self._is_currency_supported(currency):
            return False
        self._set_currency_rate(currency, rate)

    def update_currency_rate(self, currency, new_rate):
        if not self._is_currency_supported(currency):
            return False
        self._set_currency_rate(currency, new_rate)

    def _set_currency_rate(self, currency, rate):
        self.rates[currency] = rate

    def get_rate(self, currency):
        """Encapsulate Field: provide read access to rate without exposing dictionary"""
        if currency not in self.rates:
            raise ValueError(f"Currency {currency} is not supported")
        return self.rates[currency]
